-- Esquema SQLite utilizado por server.js. Ejecutar con sqlite3 sobre data/stepstyle.sqlite.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY,brand TEXT NOT NULL,name TEXT NOT NULL,gender TEXT,style TEXT,category TEXT NOT NULL,price REAL NOT NULL CHECK(price>=0),discount REAL NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),image TEXT,description TEXT,active INTEGER NOT NULL DEFAULT 1,sizes_json TEXT NOT NULL DEFAULT '[]',colors_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT,number TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id),customer_name TEXT NOT NULL,email TEXT NOT NULL,address TEXT NOT NULL,city TEXT NOT NULL,state TEXT NOT NULL,zip TEXT NOT NULL,phone TEXT NOT NULL,payment_method TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'approved',status TEXT NOT NULL DEFAULT 'pagado',subtotal REAL NOT NULL,discount REAL NOT NULL,shipping REAL NOT NULL,tax REAL NOT NULL,total REAL NOT NULL,accepted_terms INTEGER NOT NULL,terms_version TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id TEXT NOT NULL,sku TEXT NOT NULL,product_name TEXT NOT NULL,size TEXT,color TEXT,quantity INTEGER NOT NULL,unit_price REAL NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_movements (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id TEXT NOT NULL REFERENCES products(id),movement_type TEXT NOT NULL,quantity INTEGER NOT NULL,reason TEXT NOT NULL,user_id INTEGER REFERENCES users(id),order_id INTEGER REFERENCES orders(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS return_requests (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id),user_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL,details TEXT,status TEXT NOT NULL DEFAULT 'recibida',resolution TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category);
